  if (!raw)
    return null;
  try {
    const user = await resources.run.userInfo(raw);
    if (user?.id)
      return user.id;
    return raw;
  } catch (_) {
  }
  if (!looksLikeEmail(raw) && raw.length >= 20) {
    return raw;
  }
  let page = 1;
